let buf = Buffer.from(msg.payload);

let datos = {
    Sol: {},
    Bas: {},
    Rob: {},
    Cel: {},
    Cam: {}
};

let offset = 0;


// REAL agrupados por equipos
const grupos = {
    Sol: [
        "Intensidad",
        "Tension_Fuente",
        "Tension_Arco",
        "Velocidad_Hilo",
        "Caudal_Gas",
        "Presion_Gas",
        "Nivel_Gas"
    ],
    Bas: [
        "Tension",
        "Intensidad",
        "Posicion",
        "Velocidad"
    ],
    Rob: [
        "Tension",
        "Intensidad",
        "Servo_Temp1",
        "Servo_Temp2",
        "Servo_Temp3",
        "Servo_Temp4",
        "Servo_Temp5",
        "Servo_Temp6",
        "VelocidadSol",
        "DistanciaSol",
    ],
    Cel: [
        "TensionF1",
        "TensionF2",
        "TensionF3",
        "Intensidad",
        "FactorPotencia"
    ]
};

// Leer REAL (4 bytes)
for (let grupo in grupos) {
    for (let nombre of grupos[grupo]) {

        datos[grupo][nombre] = Number(
            buf.readFloatLE(offset).toFixed(2)
        );

        offset += 4;
    }
}

// UINT
datos.Cam.PuntosInt = buf.readUInt16LE(offset);
offset += 2;

datos.Cam.NSoldaduras = buf.readUInt16LE(offset);

// Salida
msg.payload = datos;

return msg;

let sol = msg.payload.Sol;

for (let variable in sol) {

    node.send({
        topic: variable,
        payload: sol[variable],
    });

}

return null;

let bas = msg.payload.Bas;

for (let variable in bas) {

    node.send({
        topic: variable,
        payload: bas[variable],
    });

}

return null;

let activas = context.get("activas") || [];
//Recorremos cada evento del mensaje
for (const evento of msg.payload) {
    //buscamos indice en activas con alarma, para saber si esta en la tabla
    const indice = activas.findIndex(n => n.alarma === evento.alarma);
    //Si esta activa y no esta añadida la añado
    if (evento.activa) {
        if (indice === -1) {
            activas.unshift(evento);
        }
    } else { //si no esta activa y esta presente la quito
        if (indice !== -1) {
            activas.splice(indice, 1); //elimina 1 elemento de posicion indice
        }
    }
}

context.set("activas", activas);

msg.payload = activas;
return msg;

const alarmas = msg.payload.Alarmas;

const nombres = [
    "Seta emergencia",
    "Puerta",
    "Barrera",
    "Emergencia",
    "Robot",
    "Camara",
    "Soldadura",
    "Bastidor",
    "MQTT",
    "Ciclo",
    "Reserva10",
    "Reserva11",
    "Reserva12",
    "Reserva13",
    "Reserva14",
    "Reserva15",
    "Reserva16",
    "Reserva17",
    "Reserva18",
    "Reserva19",
    "Reserva20",
    "Reserva21",
    "Reserva22",
    "Reserva23",
    "Reserva24",
    "Reserva25",
    "Reserva26",
    "Reserva27",
    "Reserva28",
    "Reserva29",
    "Reserva30",
    "Reserva31"
];

// Recupero valores guardados
const anterior = context.get("alarmasAnterior") ?? 0;
let historial = context.get("historialAlarmas") ?? [];

const ahora = new Date();
let eventos = [];

for (let i = 0; i < 32; i++) {
    //desplazo bit que quiero mirar y comparo con 1
    const antes = ((anterior >>> i) & 1) === 1;
    const actual = ((alarmas >>> i) & 1) === 1;

    if (antes !== actual) {

        const evento = {
            alarma: nombres[i],
            fecha: ahora.toLocaleDateString("es-ES"),
            hora: ahora.toLocaleTimeString("es-ES"),
            activa: actual,
            estado: actual
                ? '<span style="background-color:#dc3545;color:white;font-weight:bold;padding:4px 10px;border-radius:5px;display:inline-block">ALARMA</span>'
                : '<span style="background-color:#198754;color:white;font-weight:bold;padding:4px 10px;border-radius:5px;display:inline-block">OK</span>'
        };
        //meto en array de eventos la alarma detectada
        eventos.push(evento);

        // Añadir alarma al histórico
        historial.push(evento);
    }
}

// Limitar memoria (últimas 500 alarmas)
if (historial.length > 500) {
    historial = historial.slice(-500); //borra a partir del elemento 500
}

// Guardar datos
context.set("alarmasAnterior", alarmas);
context.set("historialAlarmas", historial);

// Enviar los eventos nuevos
msg.payload = eventos;

return msg;

let modo = msg.payload.Modo;

switch (modo) {
    case 0:
        msg.payload = "Emergencia";
        break;

    case 1:
        msg.payload = "Auto";
        break;

    case 2:
        msg.payload = "Manual";
        break;

    default:
        msg.payload = "Emergencia";
}

return msg;

let d = msg.payload;

//PIEZA A
let PA_OK = d.PA_CAM_OK;
let PA_NOK = d.PA_Sol_NOK + d.PA_CAM_NOK;
let PA_TOTAL = PA_OK + PA_NOK;

//PIEZA B
let PB_OK = d.PB_CAM_OK;
let PB_NOK = d.PB_Sol_NOK + d.PB_CAM_NOK;
let PB_TOTAL = PB_OK + PB_NOK;

//PIEZAS TOTALES
let Sol_OK_TOTAL = d.PA_Sol_OK + d.PB_Sol_OK;
let Sol_NOK_TOTAL = d.PA_Sol_NOK + d.PB_Sol_NOK;

let CAM_OK_TOTAL = d.PA_CAM_OK + d.PB_CAM_OK;
let CAM_NOK_TOTAL = d.PA_CAM_NOK + d.PB_CAM_NOK;

let OK_TOTAL = PA_OK + PB_OK;
let NOK_TOTAL = PA_NOK + PB_NOK;
let TOTAL = OK_TOTAL + NOK_TOTAL;


msg.payload = {
    Ciclos: d.Ciclos,

    PA_Sol_OK: d.PA_Sol_OK,
    PA_Sol_NOK: d.PA_Sol_NOK,
    PA_CAM_OK: d.PA_CAM_OK,
    PA_CAM_NOK: d.PA_CAM_NOK,
    PA_OK: PA_OK,
    PA_NOK: PA_NOK,
    PA_TOTAL: PA_TOTAL,

    PB_Sol_OK: d.PB_Sol_OK,
    PB_Sol_NOK: d.PB_Sol_NOK,
    PB_CAM_OK: d.PB_CAM_OK,
    PB_CAM_NOK: d.PB_CAM_NOK,
    PB_OK: PB_OK,
    PB_NOK: PB_NOK,
    PB_TOTAL: PB_TOTAL,

    Sol_OK_TOTAL: Sol_OK_TOTAL,
    Sol_NOK_TOTAL: Sol_NOK_TOTAL,
    CAM_OK_TOTAL: CAM_OK_TOTAL,
    CAM_NOK_TOTAL: CAM_NOK_TOTAL,

    OK_TOTAL: OK_TOTAL,
    NOK_TOTAL: NOK_TOTAL,
    TOTAL: TOTAL,

};

// GUARDAR TODO EL PAYLOAD EN MEMORIA
context.set("Produccion", msg.payload, "default");

return msg;

let estado = Number(msg.payload.Estado);
let modo = Number(msg.payload.Modo);

let ahora = Date.now();

// LEER DATOS
let datos = flow.get("tiempos", "default");
let arranque = context.get("arranque", "memoryOnly");

if (!datos) {

    datos = {

        // Tiempo general
        inicio: ahora,
        ultimoTiempo: ahora,

        //Tiempos Historico
        T_TOTAL: 0,
        T_EMER: 0,
        T_AUTO: 0,
        T_MANUAL: 0,

        T_TOTAL_H: 0,
        T_EMER_H: 0,
        T_AUTO_H: 0,
        T_MANUAL_H: 0,

        // Tiempos estados
        T_REPOSO: 0,
        T_BASTIDOR: 0,
        T_SOLDADURA: 0,
        T_CALIDAD: 0,
        T_RETORNO: 0,

        // Ciclo
        cicloInicio: null,
        reposoInicio: ahora,
        T_CICLO: 0,

        // Estado anterior
        estadoAnterior: estado,
        modoAnterior: modo
    };
}

// REINICIAR TIEMPOS DE CICLO UNA SOLA VEZ
if (!arranque) {

    datos.cicloInicio = null;
    datos.reposoInicio = ahora;

    datos.T_CICLO = 0;
    datos.T_REPOSO = 0;
    datos.T_BASTIDOR = 0;
    datos.T_SOLDADURA = 0;
    datos.T_CALIDAD = 0;
    datos.T_RETORNO = 0;

    // Evita contabilizar el tiempo transcurrido
    // desde el último mensaje antes del reinicio
    datos.ultimoTiempo = ahora;

    context.set("arranque", true, "memoryOnly");
}

// TIEMPO TRANSCURRIDO(segundos)
let dt = (ahora - datos.ultimoTiempo)/1000;

// ACUMULAR TIEMPO POR MODO
switch (datos.modoAnterior) {
    case 0:
        datos.T_EMER += dt;
        break;
    case 1:
        datos.T_AUTO += dt;
        break;
    case 2:
        datos.T_MANUAL += dt;
        break;
}

// ACUMULAR TIEMPO POR ESTADO
switch (datos.estadoAnterior) {
    case 0:
        //datos.T_REPOSO += dt;
        break;
    case 1:
        datos.T_BASTIDOR += dt;
        break;
    case 2:
        datos.T_SOLDADURA += dt;
        break;
    case 3:
        datos.T_CALIDAD += dt;
        break;
    case 4:
        datos.T_RETORNO += dt;
        break;
}

// TIEMPO TOTAL
datos.T_TOTAL = datos.T_EMER + datos.T_AUTO + datos.T_MANUAL;

// INICIO DEL CICLO: Reposo (0) → Bastidor (1)
if (datos.estadoAnterior === 0 && estado === 1) {

    // Calcular cuánto tiempo ha estado en reposo
    if (datos.reposoInicio !== null) {
        datos.T_REPOSO = (ahora - datos.reposoInicio) / 1000;
    } else {
        datos.T_REPOSO = 0;
    }
    datos.cicloInicio = ahora;

    // RESET TIEMPOS DEL CICLO
    datos.T_CICLO = 0;
    datos.T_BASTIDOR = 0;
    datos.T_SOLDADURA = 0;
    datos.T_CALIDAD = 0;
    datos.T_RETORNO = 0;
}

// FINAL DEL CICLO: Retorno (4) → Reposo (0)
if (datos.estadoAnterior === 4 && estado === 0) {
    // Comienza el tiempo de reposo
    datos.reposoInicio = ahora;

    if (datos.cicloInicio !== null) {
        //datos.T_CICLO = (ahora - datos.cicloInicio) / 1000;
        datos.T_CICLO = datos.T_BASTIDOR + datos.T_SOLDADURA + datos.T_CALIDAD + datos.T_RETORNO;
        datos.cicloInicio = null;
    }
}

// ACTUALIZAR DATOS
if (datos.cicloInicio !== null) {
    datos.T_CICLO = (ahora - datos.cicloInicio) / 1000;
}
datos.ultimoTiempo = ahora;
datos.estadoAnterior = estado;
datos.modoAnterior = modo;
// TIEMPOS EN HORAS
datos.T_TOTAL_H=Number((datos.T_TOTAL/ 3600).toFixed(2));
datos.T_EMER_H=Number((datos.T_EMER/ 3600).toFixed(2));
datos.T_AUTO_H=Number((datos.T_AUTO/ 3600).toFixed(2));
datos.T_MANUAL_H=Number((datos.T_MANUAL/ 3600).toFixed(2));

// GUARDAR DATOS
flow.set("tiempos", datos, "default");

// INDICADORES DE TIEMPO
let indicadorAuto = 0;
let indicadorManual = 0;
let indicadorEmer = 0;
let indicadorNoProduc = 0;

if (datos.T_TOTAL > 0) {
    // Tiempo automático / tiempo total
    indicadorAuto = (datos.T_AUTO / datos.T_TOTAL) * 100;
    // Tiempo manual / tiempo total
    indicadorManual = (datos.T_MANUAL / datos.T_TOTAL) * 100;
    // Tiempo emergencia / tiempo total
    indicadorEmer = (datos.T_EMER / datos.T_TOTAL) * 100;
    // Tiempo no productivo
    indicadorNoProduc =((datos.T_MANUAL + datos.T_EMER) / datos.T_TOTAL) * 100;
}

// SALIDA
msg.payload = {
    //Tiempos acumulados
    T_EMER: datos.T_EMER_H,
    T_AUTO: datos.T_AUTO_H,
    T_MANUAL: datos.T_MANUAL_H,
    T_TOTAL: datos.T_TOTAL_H,

    // INDICADORES DE TIEMPO
    IndicadorAuto: Number(indicadorAuto.toFixed(2)),
    IndicadorManual: Number(indicadorManual.toFixed(2)),
    IndicadorEmer: Number(indicadorEmer.toFixed(2)),
    IndicadorNoAuto: Number(indicadorNoProduc.toFixed(2)),

    //Tiempos ciclo actual:
    T_CICLO: datos.T_CICLO.toFixed(2),
    T_REPOSO: datos.T_REPOSO.toFixed(2),
    T_BASTIDOR: datos.T_BASTIDOR.toFixed(2),
    T_SOLDADURA: datos.T_SOLDADURA.toFixed(2),
    T_CALIDAD: datos.T_CALIDAD.toFixed(2),
    T_RETORNO: datos.T_RETORNO.toFixed(2),
};

return msg;

let tiempo = Number(msg.payload);

// Comprobar que es un número válido
if (isNaN(tiempo) || tiempo <= 0) {
    tiempo = 40;
}

// Guardar ciclo ideal
flow.set("TCicloIdeal", tiempo, "default");

// Devolver valor al Dashboard
msg.payload = tiempo;

return msg;

// INVERSA DE LA DISTRIBUCIÓN NORMAL
function normalInverse(p) {

    if (p <= 0 || p >= 1) {
        return NaN;
    }

    const a1 = -39.6968302866538;
    const a2 = 220.946098424521;
    const a3 = -275.928510446969;
    const a4 = 138.357751867269;
    const a5 = -30.6647980661472;
    const a6 = 2.50662827745924;

    const b1 = -54.4760987982241;
    const b2 = 161.585836858041;
    const b3 = -155.698979859887;
    const b4 = 66.8013118877197;
    const b5 = -13.2806815528857;

    const c1 = -0.00778489400243029;
    const c2 = -0.322396458041136;
    const c3 = -2.40075827716184;
    const c4 = -2.54973253934373;
    const c5 = 4.37466414146497;
    const c6 = 2.93816398269878;

    const d1 = 0.00778469570904146;
    const d2 = 0.32246712907004;
    const d3 = 2.445134137143;
    const d4 = 3.75440866190742;

    const pLow = 0.02425;
    const pHigh = 1 - pLow;

    let q;
    let r;

    if (p < pLow) {

        q = Math.sqrt(-2 * Math.log(p));

        return (((((c1 * q + c2) * q + c3) * q + c4) * q + c5) * q + c6) /
               ((((d1 * q + d2) * q + d3) * q + d4) * q + 1);

    }

    if (p <= pHigh) {

        q = p - 0.5;
        r = q * q;

        return (((((a1 * r + a2) * r + a3) * r + a4) * r + a5) * r + a6) * q /
               (((((b1 * r + b2) * r + b3) * r + b4) * r + b5) * r + 1);

    }

    q = Math.sqrt(-2 * Math.log(1 - p));

    return -(((((c1 * q + c2) * q + c3) * q + c4) * q + c5) * q + c6) /
             ((((d1 * q + d2) * q + d3) * q + d4) * q + 1);
}


// RECUPERAR TIEMPOS
let tiempos = flow.get("tiempos", "default");

if (!tiempos) {
    node.warn("No existen datos de tiempos");
    return null;
}

// RECUPERAR PARÁMETROS OEE
let tiempoCicloIdeal = flow.get("TCicloIdeal", "default") || 0;

// RECUPERAR OBJETIVO DPMO
let DPMO_Objetivo = Number(flow.get("DPMO_Objetivo", "default")) || 0;

// RECUPERAR CONTADORES
let d = msg.payload;

let OK = Number(d.OK_TOTAL) || 0;
let NOK = Number(d.NOK_TOTAL) || 0;
let TOTAL = Number(d.TOTAL) || 0;

// TIEMPO DE FUNCIONAMIENTO (T_AUTO en s)
let tiempoFuncionamiento = Number(tiempos.T_AUTO) || 0;
let tiempoTotal = Number(tiempos.T_TOTAL) || 0;

// DISPONIBILIDAD
let disponibilidad = 0;

if (tiempoFuncionamiento > 0) {
    disponibilidad =
        tiempoFuncionamiento / tiempoTotal;
}

// RENDIMIENTO
let rendimiento = 0;

if (tiempoFuncionamiento > 0 && tiempoCicloIdeal > 0) {
    rendimiento =(TOTAL * tiempoCicloIdeal) /tiempoFuncionamiento;
}

// CALIDAD
let calidad = 0;

if (TOTAL > 0) {
    calidad = OK / TOTAL;
}

// OEE
let OEE =disponibilidad * rendimiento * calidad;

//INDICADORES CALIDAD:
const N_oportunidades = 32;
let DPU = 0;
let DPMO = 0;
let Indicador_DPMO = 0;
let Z = 0;
let Sigma = 0;

if (TOTAL > 0) {
    // DPU
    DPU = NOK / TOTAL;

    // DPMO
    DPMO = DPU * 1000000 / N_oportunidades;

    // Comparación con objetivo
    if (DPMO_Objetivo > 0) {
        Indicador_DPMO = DPMO / DPMO_Objetivo;
    }
    // Rendimiento
    const Yield = 1 - (DPMO / 1000000);

    if (NOK === 0) {
        Sigma = 6;
    } else {
        Z = normalInverse(Yield);
        Sigma = Z + 1.5;
    }
}

// SALIDA
msg.payload = {

    // Tiempo
    TiempoTotal: tiempoTotal,
    TiempoFuncionamientoAuto: tiempoFuncionamiento,
    TiempoCicloIdeal: tiempoCicloIdeal,

    // Producción
    OK_TOTAL: OK,
    NOK_TOTAL: NOK,
    TOTAL: TOTAL,

    // KPI
    Disponibilidad: Number((disponibilidad * 100).toFixed(2)),
    Rendimiento: Number((rendimiento * 100).toFixed(2)),
    Calidad: Number((calidad * 100).toFixed(2)),
    OEE: Number((OEE * 100).toFixed(2)),

    // SIX SIGMA
    DPU: Number(DPU.toFixed(2)),
    DPMO: Number(DPMO.toFixed(2)),
    DPMO_Objetivo: DPMO_Objetivo,
    Sigma: Number(Sigma.toFixed(2))
};

return msg;

// RESETEAR TIEMPOS HISTÓRICOS

let datos = flow.get("tiempos", "default");

if (!datos) {
    node.warn("No existe la variable tiempos");
    return null;
}

// Poner históricos a cero
datos.T_TOTAL = 0;
datos.T_EMER = 0;
