// CONFIGURACIÓN GENERAL
// Ventana temporal utilizada si la variable no tiene una configuración propia.
const VENTANA_HORAS_DEFECTO = 24;

// Mínimo de muestras para calcular una tendencia.
const MIN_MUESTRAS_DEFECTO = 100;

// FUNCIÓN PARA CALCULAR PENDIENTE
function calcularPendiente(muestras) {
    if (muestras.length < MIN_MUESTRAS_DEFECTO) {
        return null;
    }

    const n = muestras.length;
    const tiempoInicial = muestras[0].timestamp;
    let sumaX = 0;
    let sumaY = 0;
    let sumaXY = 0;
    let sumaX2 = 0;

    for (let i = 0; i < n; i++) {
        // Tiempo desde la primera muestra expresado en horas
        let x = (muestras[i].timestamp - tiempoInicial) / 3600000;
        let y = muestras[i].valor;

        sumaX += x;
        sumaY += y;
        sumaXY += x * y;
        sumaX2 += x * x;
    }

    let denominador = (n * sumaX2) - (sumaX * sumaX);  

    if (denominador === 0) {
        return null;
    }

    let pendiente = ((n * sumaXY) - (sumaX * sumaY)) / denominador;

    return pendiente;
}


// RECORRER ELEMENTOS
for (let grupo of ["Sol", "Bas", "Rob", "Cel"]) {

    if (!datos[grupo]) continue;

    for (let variable in datos[grupo]) {

        let id = grupo + "/" + variable;

        // CREAR CONFIGURACIÓN SI NO EXISTE
        if (!configuracion[id]) {
            configuracion[id] = {
                min: 0,
                max: 100,
                aviso: 5,

                usarMin: true,
                usarMax: true,

                ventanaHoras: VENTANA_HORAS_DEFECTO,
                minMuestras: MIN_MUESTRAS_DEFECTO
            };
        }

        let cfg = configuracion[id];

        // COMPATIBILIDAD CON CONFIGURACIÓN EXISTENTE
        if (cfg.ventanaHoras === undefined) {
            cfg.ventanaHoras = VENTANA_HORAS_DEFECTO; 
        }
        if (cfg.minMuestras === undefined) {
            cfg.minMuestras = MIN_MUESTRAS_DEFECTO; 
        }

        // DATOS
        let valor = Number(datos[grupo][variable]);
        let min = Number(cfg.min);
        let max = Number(cfg.max);
        let aviso = Number(cfg.aviso);
        let usarMin = cfg.usarMin !== false;
        let usarMax = cfg.usarMax !== false;
        let ventanaHoras = Number(cfg.ventanaHoras);
        let minMuestras = Number(cfg.minMuestras);

        // VALIDACIÓN
        if (!isFinite(ventanaHoras) ||
            ventanaHoras <= 0) {

            ventanaHoras = VENTANA_HORAS_DEFECTO;  
        }

        if (!isFinite(minMuestras) || minMuestras < 2) {
            minMuestras = MIN_MUESTRAS_DEFECTO;    
        }

        // RANGO Y AVISOS ACTUALES
        let rango = max - min;
        let margen = rango * (aviso / 100);
        let avisoMin = min + margen;
        let avisoMax = max - margen;    

        // ESTADO ACTUAL
        let estado = "OK";

        if ((usarMin && valor <= min) || (usarMax && valor >= max)) {
            estado = "ALARMA";
        }
        else if ((usarMin && valor <= avisoMin) || (usarMax && valor >= avisoMax)) {
            estado = "AVISO";
        }

        // HISTÓRICO
        if (!historico[id]) {
            historico[id] = [];
        }

        // Añadir nueva muestra
        historico[id].push({
            valor: valor,
            timestamp: Date.now()

        });


        // ELIMINAR MUESTRAS FUERA DE LA VENTANA
        let ahora = Date.now();
        let limiteTiempo = ahora - (ventanaHoras * 3600000);

        historico[id] =
            historico[id].filter(
                muestra =>
                    muestra.timestamp >= limiteTiempo
            );


        let muestras = historico[id];

        // CALCULAR PENDIENTE
        let pendiente = null;

        if (muestras.length >= minMuestras) {
            pendiente = calcularPendiente(muestras);    
        }

        // TIEMPO HASTA LÍMITE
        let tiempoLimite = null;

        if (pendiente !== null && isFinite(pendiente) &&
            pendiente !== 0 && rango > 0) {

            // VA HACIA EL MÁXIMO
            if (pendiente > 0 && usarMax) {
                let distancia = max - valor;

                if (distancia <= 0) {
                    //Se ha llegado al límite
                    tiempoLimite = 0;
                }
                else {
                    tiempoLimite = distancia / pendiente;  
                }
            }
            // VA HACIA EL MÍNIMO
            else if (pendiente < 0 && usarMin){
                let distancia = valor - min;

                if (distancia <= 0) {
                    // Ya está en el límite
                    tiempoLimite = 0;

                }
                else {
                    tiempoLimite = distancia / Math.abs(pendiente);       
                }
            }
        }

        // FORMATEAR PENDIENTE
        let pendienteSalida = null;

        if (pendiente !== null && isFinite(pendiente)) {

            pendienteSalida = Number(pendiente.toFixed(3));
        }

        // FORMATEAR TIEMPO
        let tiempoSalida = null;

        if (
            tiempoLimite !== null &&
            tiempoLimite !== undefined &&
             Number.isFinite(Number(tiempoLimite))
        ) {
            tiempoSalida = Number(Number(tiempoLimite).toFixed(1));
        }

        // CREAR FILA
        filas.push({
            id: id,
            equipo: grupo,
            variable: variable,
            valor: Number(valor.toFixed(2)),
            unidad: unidades[id] || "", 
            min: min,
            max: max,
            aviso: aviso,
            usarMin: usarMin,
            usarMax: usarMax,
            estado: estado,

            // PREDICCIÓN
            pendienteHora: pendienteSalida,
            tiempoLimite: tiempoSalida, 

            // Información de la ventana
            ventanaHoras: ventanaHoras,
            muestras: muestras.length

        });
    }
}

// GUARDAR
flow.set("config_variables", configuracion, "default");
flow.set("historico_tendencias", historico);  

// SALIDA
msg.payload = filas;

return msg;

let cam = msg.payload.Cam;

for (let variable in cam) {

    node.send({
        topic: variable,
        payload: cam[variable],
    });

}

return null;
